// Some portions generated by Claude
import assert from "node:assert/strict";
import test from "node:test";
import {
  facetModel,
  NO_MATCH_VALUE,
  TYPE_FACET_ID,
  valuesInRange,
} from "../../../main/frontend/graph-explorer/graph-facets.ts";

const RDF_TYPE = "http://www.w3.org/1999/02/22-rdf-syntax-ns#type";
const LABEL = "http://www.w3.org/2000/01/rdf-schema#label";
const XSD = "http://www.w3.org/2001/XMLSchema#";
const person = { id: "urn:Person", label: "Person" };
const org = { id: "urn:Org", label: "Organization" };
const iri = (id, types) => ({ id, label: id.slice(4), kind: "iri", types });
const number = (value) => ({ id: `"${value}"`, label: String(value), termValue: String(value), kind: "literal", datatype: `${XSD}integer` });
const date = (value) => ({ id: `"${value}"`, label: value, termValue: value, kind: "literal", datatype: `${XSD}date` });
const edge = (source, predicate, target) => ({ id: `${source} ${predicate} ${target}`, source, predicate, label: predicate.slice(4), target });

const resources = [
  iri("urn:alice", [person]), iri("urn:bob", [person]), iri("urn:carol", [person]), iri("urn:dave", [person]),
  iri("urn:acme", [org]), iri("urn:globex", [org]),
];
const literals = [number(29), number(34), number(39), number(46), date("1999-04-01"), date("2005-10-10"),
  { id: '"Alice"', label: "Alice", kind: "literal" }];
const edges = [
  edge("urn:alice", "urn:worksFor", "urn:acme"), edge("urn:bob", "urn:worksFor", "urn:acme"),
  edge("urn:carol", "urn:worksFor", "urn:globex"),
  edge("urn:alice", "urn:age", '"39"'), edge("urn:bob", "urn:age", '"34"'), edge("urn:carol", "urn:age", '"46"'),
  edge("urn:dave", "urn:age", '"29"'),
  edge("urn:acme", "urn:founded", '"1999-04-01"'), edge("urn:globex", "urn:founded", '"2005-10-10"'),
  edge("urn:alice", "urn:knows", "urn:bob"),
  edge("urn:alice", LABEL, '"Alice"'),
  edge("urn:alice", RDF_TYPE, "urn:Person"),
];
const nodeById = new Map([...resources, ...literals].map((node) => [node.id, node]));
const model = (selection = new Map()) =>
  facetModel({
    nodes: resources,
    edges,
    nodeById,
    selection,
    typesOf: (node) => node.types ?? [],
    hiddenPredicates: new Set([RDF_TYPE, LABEL]),
  });
const facet = (result, id) => result.facets.find((candidate) => candidate.id === id);
const counts = (result, id) =>
  Object.fromEntries((facet(result, id)?.values ?? []).map((value) => [value.label, value.count]));

test("without a selection every node matches and facets come type first, then by how many nodes have them", () => {
  const result = model();
  assert.equal(result.matches.size, 6);
  assert.deepEqual(result.facets.map((candidate) => candidate.label), ["Type", "age", "worksFor", "founded", "knows"]);
  assert.deepEqual(counts(result, TYPE_FACET_ID), { Person: 4, Organization: 2 });
});

test("rdf:type and name properties are not offered as property filters", () => {
  const ids = model().facets.map((candidate) => candidate.id);
  assert.ok(!ids.includes(RDF_TYPE));
  assert.ok(!ids.includes(LABEL));
});

test("values are OR within a filter and AND across filters", () => {
  const either = model(new Map([["urn:worksFor", new Set(["urn:acme", "urn:globex"])]]));
  assert.deepEqual([...either.matches].sort(), ["urn:alice", "urn:bob", "urn:carol"]);
  const both = model(new Map([["urn:worksFor", new Set(["urn:acme"])], ["urn:knows", new Set(["urn:bob"])]]));
  assert.deepEqual([...both.matches], ["urn:alice"]);
});

test("counts follow the other filters, so a choice that would match nothing is not offered", () => {
  const organizations = model(new Map([[TYPE_FACET_ID, new Set(["urn:Org"])]]));
  assert.deepEqual([...organizations.matches].sort(), ["urn:acme", "urn:globex"]);
  // People-only filters have no organizations left to count and disappear.
  assert.equal(facet(organizations, "urn:worksFor"), undefined);
  assert.equal(facet(organizations, "urn:age"), undefined);
  assert.ok(facet(organizations, "urn:founded"));
  // A filter does not narrow its own counts: the other types stay available.
  assert.deepEqual(counts(organizations, TYPE_FACET_ID), { Person: 4, Organization: 2 });

  const atAcme = model(new Map([["urn:worksFor", new Set(["urn:acme"])]]));
  assert.deepEqual(counts(atAcme, TYPE_FACET_ID), { Person: 2 });
  assert.deepEqual(counts(atAcme, "urn:worksFor"), { acme: 2, globex: 1 });
});

test("a selected value stays visible even when the other filters leave it without matches", () => {
  const result = model(new Map([[TYPE_FACET_ID, new Set(["urn:Org"])], ["urn:worksFor", new Set(["urn:acme"])]]));
  assert.equal(result.matches.size, 0);
  assert.deepEqual(counts(result, "urn:worksFor"), { acme: 0 });
});

test("numbers and dates with several values become ranges", () => {
  const result = model();
  const age = facet(result, "urn:age");
  assert.deepEqual(age.range && { kind: age.range.kind, min: age.range.min, max: age.range.max }, { kind: "number", min: 29, max: 46 });
  assert.deepEqual(valuesInRange(age, "30", "40"), new Set(['"34"', '"39"']));
  assert.deepEqual(valuesInRange(age, "", "30"), new Set(['"29"']));
  assert.deepEqual(valuesInRange(age, "50", ""), new Set([NO_MATCH_VALUE]));
  assert.equal(facet(result, "urn:founded").range, undefined, "two dates read better as two choices");

  const ranged = model(new Map([["urn:age", valuesInRange(age, "30", "40")]]));
  assert.deepEqual([...ranged.matches].sort(), ["urn:alice", "urn:bob"]);
  assert.equal(model(new Map([["urn:age", new Set([NO_MATCH_VALUE])]])).matches.size, 0);
});

test("dates become ranges once there are enough of them", () => {
  const days = ["2001-01-01", "2002-02-02", "2003-03-03", "2004-04-04"].map(date);
  const people = resources.slice(0, 4);
  const result = facetModel({
    nodes: people,
    edges: people.map((node, index) => edge(node.id, "urn:born", days[index].id)),
    nodeById: new Map([...people, ...days].map((node) => [node.id, node])),
    selection: new Map(),
    typesOf: (node) => node.types ?? [],
    hiddenPredicates: new Set(),
  });
  const born = facet(result, "urn:born");
  assert.equal(born.range.kind, "date");
  assert.deepEqual(valuesInRange(born, "2002-01-01", "2003-12-31"), new Set(['"2002-02-02"', '"2003-03-03"']));
});
